CREATE OR REPLACE FUNCTION public.get_financeiro_month_totals(p_tipo text, p_start date, p_end date, p_banco_id text DEFAULT NULL) RETURNS TABLE (total_previsto numeric, total_efetivado numeric, total_previsto_pendente numeric) LANGUAGE sql STABLE SET search_path = '' AS $$ SELECT COALESCE(SUM(valor), 0) AS total_previsto, COALESCE(SUM(valor) FILTER (WHERE status = 'EFETIVADO'), 0) AS total_efetivado, COALESCE(SUM(valor) FILTER (WHERE status = 'PREVISTO'), 0) AS total_previsto_pendente FROM public.lancamentos_financeiros WHERE tipo = p_tipo AND data_competencia >= p_start AND data_competencia < p_end AND (p_banco_id IS NULL OR banco_id = p_banco_id) $$